'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var format = require( '@stdlib/string/format' );
var defaults = require( './../defaults.js' );


// VARIABLES //

var EMPTY_STRING = [ '' ];


// MAIN //

/**
* Adds a "general" menu to an editor.
*
* @private
* @param {Editor} editor - editor instance
* @param {Object} conf - editor configuration
* @returns {Controller} menu controller
*/
function addMenu( editor, conf ) {
	var controller;
	var folder;
	var keys;
	var def;
	var d;
	var k;
	var i;

	keys = objectKeys( conf );
	if ( keys.length === 0 ) {
		return;
	}
	folder = editor.addFolder( 'Title' );
	folder.close();

	def = defaults.title;

	// TODO: consider refactoring to a hash look-up table where the values are short(ish) functions
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		d = def[ k ];
		if ( k === 'align' ) {
			folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'anchor' ) {
			folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'angle' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'baseline' ) {
			folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'color' ) {
			folder.addColor( conf, k );
		} else if ( k === 'dx' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'dy' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'font' ) {
			folder.add( conf, k );
		} else if ( k === 'fontSize' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'fontStyle' ) {
			folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'fontWeight' ) {
			folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'frame' ) {
			folder.add( conf, k, d.values );
		} else if ( k === 'limit' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'lineHeight' ) {
			folder.add( conf, k )
				.min( d.min );
		} else if ( k === 'offset' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'orient' ) {
			folder.add( conf, k, d.values );
		} else if ( k === 'subtitle' ) {
			folder.add( conf, k );
		} else if ( k === 'subtitleColor' ) {
			folder.addColor( conf, k );
		} else if ( k === 'subtitleFont' ) {
			folder.add( conf, k );
		} else if ( k === 'subtitleFontSize' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'subtitleFontStyle' ) {
			folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'subtitleFontWeight' ) {
			folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'subtitleLineHeight' ) {
			folder.add( conf, k )
				.min( d.min );
		} else if ( k === 'subtitlePadding' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'text' ) {
			folder.add( conf, k );
		} else {
			console.log( 'Unrecognized property in editor configuration. Key: %s.', k );
		}
	}
	return folder;
}


// EXPORTS //

module.exports = addMenu;
